-- Créer la base de données
CREATE DATABASE clubmanager;

-- Utiliser la base de données
USE clubmanager;

CREATE TABLE status (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nom_role VARCHAR(50) NOT NULL,
    description TEXT
);


-- Créer la table des genres
CREATE TABLE genres (
  id INT AUTO_INCREMENT PRIMARY KEY,
  genre_name VARCHAR(50) NOT NULL
);


-- Créer la table des plans tarifaires
CREATE TABLE plans_tarifaires (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nom_plan VARCHAR(50) NOT NULL,
    prix DECIMAL(10, 2) NOT NULL,
    periode VARCHAR(20) NOT NULL,
    description TEXT
);

-- Créer la table des grade_ids
CREATE TABLE grades (
    id INT AUTO_INCREMENT PRIMARY KEY,
    grade_id VARCHAR(100) NOT NULL
);

CREATE TABLE groupes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nom VARCHAR(100) NOT NULL,  -- Nom du groupe
    description TEXT,  -- Description du groupe (facultatif)
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP  -- Date de création du groupe
);


-- Créer la table des utilisateurs
CREATE TABLE utilisateurs (
    id INT AUTO_INCREMENT PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    nom_utilisateur VARCHAR(50) NOT NULL,
    email VARCHAR(100) NOT NULL UNIQUE,  -- Unicité de l'email
    genre_id INT,  -- Clé étrangère pour le genre
    date_of_birth DATE NOT NULL,
    password VARCHAR(255) NOT NULL,  -- Spécification de la taille du champ pour le mot de passe
    status_id INT DEFAULT 1,  -- Clé étrangère pour le statut
    grade_id INT DEFAULT 1,  -- Référence à l'ID de la table `grades`
    abonnement_id INT,  -- Clé étrangère pour le tarif (plan)
    
    -- Ajout des clés étrangères
    FOREIGN KEY (genre_id) REFERENCES genres(id),
    FOREIGN KEY (abonnement_id) REFERENCES plans_tarifaires(id),
    FOREIGN KEY (grade_id) REFERENCES grades(id),  -- Référence correcte à `grades`
    FOREIGN KEY (status_id) REFERENCES status(id)  -- Clé étrangère vers la table `status`
);


-- Création de la table tailles
CREATE TABLE tailles (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nom VARCHAR(20) NOT NULL  -- Exemple: "S", "M", "L", "XL"
);

-- Création de la table categories (si tu en as une)
CREATE TABLE categories (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nom VARCHAR(100) NOT NULL
);

-- Création de la table articles
CREATE TABLE articles (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nom VARCHAR(100) NOT NULL,  -- Nom de l'article
    description TEXT,  -- Description de l'article
    prix DECIMAL(10, 2) NOT NULL,  -- Prix de l'article
    image_url VARCHAR(255),  -- URL de l'image de l'article
    categorie_id INT,  -- Référence à la table des catégories (si tu as une table de catégories)
    
    -- Clé étrangère vers une table de catégories (si tu en as une)
    FOREIGN KEY (categorie_id) REFERENCES categories(id)
);

-- Création de la table stocks
CREATE TABLE stocks (
    id INT AUTO_INCREMENT PRIMARY KEY,
    article_id INT,  -- Clé étrangère vers la table des articles
    taille_id INT,   -- Clé étrangère vers la table des tailles
    quantite INT NOT NULL,  -- Quantité en stock pour cette taille d'article
    
    -- Clés étrangères
    FOREIGN KEY (article_id) REFERENCES articles(id) ON DELETE CASCADE,
    FOREIGN KEY (taille_id) REFERENCES tailles(id) ON DELETE CASCADE
);

CREATE TABLE images (
  id SERIAL PRIMARY KEY,
  article_id INT NOT NULL,
  url TEXT NOT NULL,
  is_main BOOLEAN DEFAULT FALSE,
  FOREIGN KEY (article_id) REFERENCES articles(id) ON DELETE CASCADE
);


-- Recréer la table commandes avec ON DELETE CASCADE
CREATE TABLE commandes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    utilisateur_id INT,  -- Référence à l'utilisateur ayant passé la commande
    date_commande TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  -- Date et heure de la commande
    statut ENUM('en attente', 'payée', 'expédiée', 'annulée') DEFAULT 'en attente',  -- Statut de la commande

    -- Clé étrangère vers la table des utilisateurs avec ON DELETE CASCADE
    FOREIGN KEY (utilisateur_id)
    REFERENCES utilisateurs(id)
    ON DELETE CASCADE
);

-- Création de la table commande_articles
CREATE TABLE commande_articles (
    id INT AUTO_INCREMENT PRIMARY KEY,
    commande_id INT,  -- Référence à la commande
    article_id INT,   -- Référence à l'article
    taille_id INT,    -- Référence à la taille de l'article (si applicable)
    quantite INT NOT NULL,  -- Quantité de l'article commandée
    prix DECIMAL(10, 2) NOT NULL,  -- Prix de l'article au moment de la commande
    
    -- Clés étrangères
    FOREIGN KEY (commande_id) REFERENCES commandes(id) ON DELETE CASCADE,
    FOREIGN KEY (article_id) REFERENCES articles(id) ON DELETE CASCADE,
    FOREIGN KEY (taille_id) REFERENCES tailles(id) ON DELETE CASCADE
);




-- Créer la table des cours récurrents (doit être créé avant `cours`)
CREATE TABLE cours_recurrent (
    id INT AUTO_INCREMENT PRIMARY KEY,
    type_cours VARCHAR(255),        -- Type de cours (ex: Grappling, JJB)
    jour_semaine INT,               -- Jour de la semaine (1 pour dimanche, 2 pour lundi, etc.)
    heure_debut TIME,               -- Heure de début
    heure_fin TIME,                 -- Heure de fin
    active BOOLEAN DEFAULT TRUE     -- Si la récurrence est active ou non
);

-- Créer la table des cours (fait référence à `cours_recurrent`)
CREATE TABLE cours (
    id INT AUTO_INCREMENT PRIMARY KEY,
    date_cours DATE NOT NULL,
    type_cours VARCHAR(50) NOT NULL,
    heure_debut TIME NOT NULL,
    heure_fin TIME NOT NULL,
    cours_recurrent_id INT,
    FOREIGN KEY (cours_recurrent_id) REFERENCES cours_recurrent(id) ON DELETE CASCADE
);


-- Créer la table des inscriptions avec ON DELETE CASCADE (fait référence à `cours` et `utilisateurs`)
CREATE TABLE inscriptions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    utilisateur_id INT,  -- Clé étrangère vers la table utilisateurs
    cours_id INT,        -- Clé étrangère vers la table cours
    date_inscription TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    status_id BOOLEAN DEFAULT NULL,
    FOREIGN KEY (utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE,
    FOREIGN KEY (cours_id) REFERENCES cours(id) ON DELETE CASCADE
);


-- Créer la table des professeurs
CREATE TABLE professeurs (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nom VARCHAR(255) NOT NULL,
    prenom VARCHAR(255) NOT NULL,
    email VARCHAR(255) UNIQUE,
    grade_id INT,
    status_id INT,
    FOREIGN KEY (grade_id) REFERENCES grades(id),
    FOREIGN KEY (status_id) REFERENCES status(id)
);

-- Créer la table des cours récurrents-professeurs (fait référence à `cours_recurrent` et `professeur`)
CREATE TABLE cours_recurrent_professeur (
    id INT AUTO_INCREMENT PRIMARY KEY,
    cours_recurrent_id INT NOT NULL,
    professeur_id INT NOT NULL,
    FOREIGN KEY (cours_recurrent_id) REFERENCES cours_recurrent(id) ON DELETE CASCADE,
    FOREIGN KEY (professeur_id) REFERENCES professeurs(id) ON DELETE CASCADE
);




-- Insérer les jours de la semaine dans la table cours_recurrent



-- Variables de saison (2 ans à partir de septembre courant ou précédent)
SET @current_year = YEAR(CURDATE());
SET @season_start = STR_TO_DATE(
  CONCAT(
    CASE WHEN MONTH(CURDATE()) < 9 THEN @current_year - 1 ELSE @current_year END,
    '-09-01'
  ), '%Y-%m-%d'
);
SET @season_end = DATE_ADD(@season_start, INTERVAL 730 DAY);

-- Table temporaire avec uniquement les jours valides pour les cours
CREATE TEMPORARY TABLE IF NOT EXISTS dates_valides (
    date_cours DATE,
    jour_semaine INT
);
TRUNCATE TABLE dates_valides;

-- Générer les dates valides (dimanche, lundi, jeudi, samedi)
SELECT
  DATE_ADD(@season_start, INTERVAL seq DAY) AS date_cours,
  DAYOFWEEK(DATE_ADD(@season_start, INTERVAL seq DAY)) AS jour_semaine
FROM (
    SELECT a.N + b.N * 10 + c.N * 100 AS seq
    FROM
      (SELECT 0 AS N UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
       UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a,
      (SELECT 0 AS N UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
       UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b,
      (SELECT 0 AS N UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
       UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7) c
) numbers
WHERE DAYOFWEEK(DATE_ADD(@season_start, INTERVAL seq DAY)) IN (1, 2, 5, 7)
  AND DATE_ADD(@season_start, INTERVAL seq DAY) <= @season_end;

-- Insérer dans cours de manière cohérente
SELECT 
    dv.date_cours,
    cr.type_cours,
    CASE 
        WHEN dv.jour_semaine = 2 THEN '19:30:00'    -- Lundi
        WHEN dv.jour_semaine = 5 THEN '19:30:00'    -- Jeudi
        WHEN dv.jour_semaine = 7 THEN '12:00:00'    -- Samedi
        WHEN dv.jour_semaine = 1 THEN '14:15:00'    -- Dimanche
    END AS heure_debut,
    CASE 
        WHEN dv.jour_semaine = 2 THEN '21:15:00'
        WHEN dv.jour_semaine = 5 THEN '21:15:00'
        WHEN dv.jour_semaine = 7 THEN '13:30:00'
        WHEN dv.jour_semaine = 1 THEN '16:00:00'
    END AS heure_fin,
    cr.id AS cours_recurrent_id
FROM dates_valides dv
JOIN cours_recurrent cr ON cr.jour_semaine = dv.jour_semaine;






-- Créer la table des réservations avec ON DELETE CASCADE
CREATE TABLE reservations (
    id INT AUTO_INCREMENT PRIMARY KEY,
    utilisateur_id INT,
    cours_id INT,
    FOREIGN KEY (utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE,
    FOREIGN KEY (cours_id) REFERENCES cours(id) ON DELETE CASCADE,
    UNIQUE (utilisateur_id, cours_id) -- pour éviter les réservations en double pour le même utilisateur et le même cours
);

-- Créer la table des paiements
CREATE TABLE paiements (
    id INT AUTO_INCREMENT PRIMARY KEY,
    utilisateur_id INT,  -- Clé étrangère vers la table utilisateurs
    montant DECIMAL(10, 2) NOT NULL,  -- Montant du paiement
    date_paiement DATE NOT NULL,  -- Date du paiement
    statut ENUM('validé', 'en attente', 'pas encore effectué') DEFAULT 'pas encore effectué',  -- Statut du paiement
    abonnement_id INT,  -- Référence à l'abonnement de l'utilisateur (table plans_tarifaires)
    periode_debut DATE,  -- Date de début de la période couverte par ce paiement
    periode_fin DATE,  -- Date de fin de la période couverte par ce paiement
    
    -- Ajout des clés étrangères
    FOREIGN KEY (utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE,
    FOREIGN KEY (abonnement_id) REFERENCES plans_tarifaires(id) ON DELETE SET NULL,
    
    -- Contrainte UNIQUE pour un paiement unique par période pour chaque utilisateur
    UNIQUE (utilisateur_id, periode_debut)
);



CREATE TABLE groupes_utilisateurs (
    id INT AUTO_INCREMENT PRIMARY KEY,
    groupe_id INT,  -- Clé étrangère vers le groupe
    utilisateur_id INT,  -- Clé étrangère vers l'utilisateur
    date_ajout TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  -- Date d'ajout de l'utilisateur au groupe
    
    FOREIGN KEY (groupe_id) REFERENCES groupes(id) ON DELETE CASCADE,
    FOREIGN KEY (utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE
);



CREATE TABLE groupe_membres (
  id INT AUTO_INCREMENT PRIMARY KEY,
  groupe_id INT NOT NULL,
  utilisateur_id INT NOT NULL,
  joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  
  FOREIGN KEY (groupe_id) REFERENCES groupes(id) ON DELETE CASCADE,
  FOREIGN KEY (utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE
);

CREATE TABLE messages (
  id INT AUTO_INCREMENT PRIMARY KEY,
  sender_id INT NOT NULL,         -- Qui envoie
  receiver_id INT DEFAULT NULL,   -- À qui ? (null si c'est pour un groupe)
  groupe_id INT DEFAULT NULL,     -- Pour les chats de groupe
  contenu TEXT NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

  -- Clés étrangères
  FOREIGN KEY (sender_id) REFERENCES utilisateurs(id) ON DELETE CASCADE,
  FOREIGN KEY (receiver_id) REFERENCES utilisateurs(id) ON DELETE CASCADE,
  FOREIGN KEY (groupe_id) REFERENCES groupes(id) ON DELETE CASCADE
);

CREATE TABLE message_status (
  id INT AUTO_INCREMENT PRIMARY KEY,
  message_id INT NOT NULL,
  utilisateur_id INT NOT NULL,  -- L'utilisateur qui a vu ou non le message
  status ENUM('vu', 'non vu') DEFAULT 'non vu',  -- Statut du message
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

  FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE,
  FOREIGN KEY (utilisateur_id) REFERENCES utilisateurs(id) ON DELETE CASCADE
);



CREATE TABLE messages_personnalises (
    id INT AUTO_INCREMENT PRIMARY KEY,
    utilisateur_id INT,  -- Clé étrangère vers l'utilisateur qui crée le message
    contenu TEXT NOT NULL,  -- Contenu du message personnalisé
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  -- Date de création du message personnalisé
    
    FOREIGN KEY (utilisateur_id) REFERENCES utilisateurs(id)
);

CREATE TABLE types_messages_personnalises (
  id INT PRIMARY KEY AUTO_INCREMENT,
  title VARCHAR(255) NOT NULL,
  content TEXT NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);



CREATE TABLE notifications (
    id INT AUTO_INCREMENT PRIMARY KEY,
    utilisateur_id INT,  -- Clé étrangère vers l'utilisateur
    message_id INT,  -- Clé étrangère vers le message
    vu BOOLEAN DEFAULT FALSE,  -- Indicateur si le message a été vu ou non
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  -- Date de la notification
    
    FOREIGN KEY (utilisateur_id) REFERENCES utilisateurs(id),
    FOREIGN KEY (message_id) REFERENCES messages(id)
);




